import{_ as r,o as a,c as o,ag as n}from"./chunks/framework.8tqBsFWt.js";const d=JSON.parse('{"title":"The morning briefing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/morning-briefing.md","filePath":"guide/morning-briefing.md"}'),t={name:"guide/morning-briefing.md"};function i(s,e,h,g,m,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="the-morning-briefing" tabindex="-1">The morning briefing <a class="header-anchor" href="#the-morning-briefing" aria-label="Permalink to &quot;The morning briefing&quot;">​</a></h1><p>Every weekday morning, VERA sends each team member a personalised summary in Slack. What you see depends on your role.</p><hr><h2 id="for-team-members" tabindex="-1">For team members <a class="header-anchor" href="#for-team-members" aria-label="Permalink to &quot;For team members&quot;">​</a></h2><p>Your morning message has two parts.</p><p><strong>Recent time</strong> — your hours from the last five working days, grouped by project. A quick check that nothing&#39;s missing before the day starts.</p><p><strong>Your work plan</strong> — a table showing every project you&#39;re currently allocated to, with columns for how many hours are in your plan, how many you&#39;ve logged so far, and how many remain. This is what you should be working on today.</p><p>If something looks wrong — a project you&#39;re not working on, missing hours, or an envelope you don&#39;t recognise — message VERA and they&#39;ll help you work out what&#39;s happened.</p><hr><h2 id="for-managers-and-owners" tabindex="-1">For managers and owners <a class="header-anchor" href="#for-managers-and-owners" aria-label="Permalink to &quot;For managers and owners&quot;">​</a></h2><p>Your morning message covers the whole portfolio.</p><p><strong>Recent time</strong> — same as team members, across your whole team.</p><p><strong>Retainer status</strong> — for any retainer projects you manage, a summary of where each period stands: hours used, hours remaining, and whether the current pace is sustainable.</p><p><strong>Project pace</strong> — a burn-down view of projects with deadlines. Sorted by which are most behind schedule, flagged with 🔴 (critical), ⚠️ (at risk), or ✅ (on track).</p><p><strong>Pending time-off requests</strong> — any team member requests waiting for your approval, shown as a 📅 block.</p><p><strong>Items needing attention</strong> — any unresolved issues flagged as 🔴 that need a decision or action.</p><hr><h2 id="the-evening-check-in" tabindex="-1">The evening check-in <a class="header-anchor" href="#the-evening-check-in" aria-label="Permalink to &quot;The evening check-in&quot;">​</a></h2><p>At 5pm, if you haven&#39;t hit your target hours for the day, VERA sends a brief reminder. For managers and owners, this also includes any critical project alerts that have come up during the day.</p><p>If you&#39;ve already logged enough for the day, no message is sent.</p><hr><h2 id="triggering-the-briefing-manually" tabindex="-1">Triggering the briefing manually <a class="header-anchor" href="#triggering-the-briefing-manually" aria-label="Permalink to &quot;Triggering the briefing manually&quot;">​</a></h2><p>You can ask VERA for a summary at any time:</p><blockquote><p>&quot;Give me my morning summary&quot;</p></blockquote><blockquote><p>&quot;How are my projects looking today?&quot;</p></blockquote><blockquote><p>&quot;What&#39;s pending for approval?&quot;</p></blockquote><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="/blog/19-the-briefing.html">The Briefing That Replaced the Monday Check-in</a> — how the morning summary was designed and what it&#39;s actually trying to answer</li></ul>',28)])])}const c=r(t,[["render",i]]);export{d as __pageData,c as default};
